function transform(input) {
    var result = {
        data: [],
        metadata: {
            eventData: {
                indicatorSysid: gs.getProperty('discovery.pattern.indicator.sysid', '')
            },
            dataSourceLabel: "Discovery Effectiveness",
            series: [
                { label: "Success Rate", id: "value", type: "value" },
                { label: "Forecast", id: "forecast", type: "forecast" },
                { label: "Forecast Range", lower: "forecastRangeLower", upper: "forecastRangeUpper", id: "forecastRange", type: "band" },
                { label: "Trend", id: "trend", type: "trend" },
                { label: "Confidence Band", lower: "confidenceBandRangeLower", upper: "confidenceBandRangeUpper", id: "confidenceBand", type: "band" },
                { label: "Prediction Band", lower: "predictionBandRangeLower", upper: "predictionBandRangeUpper", id: "predictionBand", type: "band" }
            ],
            aggregate: { fieldType: "decimal" },
            format: {
                unitFormat: "{0}%",
                frequency: "daily",
                precision: 2
            }
        },
        thresholds: [
            { label: "Target Success Rate", value: 80, type: "global" }
        ],
        comments: []
    };

    var patterns = getDiscoveryData();
    var analytics = calculateAnalytics(patterns);

    result.data = analytics.map(function(item) {
        return {
            timestamp: item.timestamp.toString(),
            value: item.actual_rate ? item.actual_rate.toFixed(2) : "",
            forecast: item.forecast ? item.forecast.toFixed(2) : "",
            forecastRangeLower: item.forecast_lower ? item.forecast_lower.toFixed(2) : "",
            forecastRangeUpper: item.forecast_upper ? item.forecast_upper.toFixed(2) : "",
            trend: item.trend ? item.trend.toFixed(2) : "",
            confidenceBandRangeLower: item.confidence_lower ? item.confidence_lower.toFixed(2) : "",
            confidenceBandRangeUpper: item.confidence_upper ? item.confidence_upper.toFixed(2) : "",
            predictionBandRangeLower: item.prediction_lower ? item.prediction_lower.toFixed(2) : "",
            predictionBandRangeUpper: item.prediction_upper ? item.prediction_upper.toFixed(2) : ""
        };
    });

    return [result];
}

function getDiscoveryData() {
    var patterns = [];

    // Query discovery status
    var gr = new GlideRecord('discovery_status');
    gr.addQuery('sys_created_on', '>=', gs.daysAgoStart(90));
    gr.addNotNullQuery('state');  // Ensure state is populated
    gr.orderBy('sys_created_on');
    gr.query();

    while (gr.next()) {
        var success = 0;
        // Check for successful discovery based on state
        if (gr.state == 'Complete' || gr.state == 'Successful') {
            success = 1;
        }

        patterns.push({
            timestamp: gr.sys_created_on.getGlideObject().getNumericValue(),
            success: success,
            total: 1
        });
    }

    // Optionally include discovery log results
    var logGr = new GlideRecord('discovery_log');
    logGr.addQuery('sys_created_on', '>=', gs.daysAgoStart(90));
    logGr.addNotNullQuery('status');
    logGr.orderBy('sys_created_on');
    logGr.query();

    while (logGr.next()) {
        patterns.push({
            timestamp: logGr.sys_created_on.getGlideObject().getNumericValue(),
            success: (logGr.status == 'successful') ? 1 : 0,
            total: 1
        });
    }

    return patterns;
}

function calculateAnalytics(patterns) {
    var analytics = [];
    var dailyStats = {};

    // Group by day
    patterns.forEach(function(pattern) {
        var dayKey = new GlideDateTime(pattern.timestamp).getDate();
        if (!dailyStats[dayKey]) {
            dailyStats[dayKey] = { success: 0, total: 0, timestamp: pattern.timestamp };
        }
        dailyStats[dayKey].success += pattern.success;
        dailyStats[dayKey].total += pattern.total;
    });

    // Calculate rates
    Object.values(dailyStats).forEach(function(stat) {
        var rate = (stat.success / stat.total) * 100;
        analytics.push({
            timestamp: stat.timestamp,
            actual_rate: rate,
            trend: calculateTrend(rate),
            forecast: null,
            forecast_lower: null,
            forecast_upper: null,
            confidence_lower: rate * 0.95,
            confidence_upper: rate * 1.05,
            prediction_lower: rate * 0.90,
            prediction_upper: rate * 1.10
        });
    });

    // Add forecast
    if (analytics.length > 0) {
        var lastRate = analytics[analytics.length - 1].actual_rate;

        for (var i = 1; i <= 7; i++) {
            var lastTimestamp = analytics[analytics.length - 1].timestamp;
            var nextDay = new GlideDateTime(lastTimestamp);
            nextDay.addDaysUTC(1);

            analytics.push({
                timestamp: nextDay.getNumericValue(),
                actual_rate: null,
                trend: null,
                forecast: lastRate,
                forecast_lower: lastRate * 0.85,
                forecast_upper: lastRate * 1.15,
                confidence_lower: null,
                confidence_upper: null,
                prediction_lower: null,
                prediction_upper: null
            });
        }
    }

    return analytics;
}

function calculateTrend(currentRate) {
    return currentRate + (Math.random() * 2 - 1);
}
